using be;

namespace api;

// a new set of holiday rules sent by the system owner (admin).
// id is not here: it is generated by the db
public class RuleSetDTO
{
    // the rules apply from this date, must be the 1st of a month
    public DateOnly effective_from { get; set; }

    // weeks 1-5
    public decimal weeks1to5_month_rate { get; set; }
    public int weeks1to5_earning_start_month { get; set; }
    public int weeks1to5_earning_end_month { get; set; }
    public int weeks1to5_usage_start_month { get; set; }
    public int weeks1to5_usage_start_year_offset { get; set; }
    public int weeks1to5_usage_end_month { get; set; }
    public int weeks1to5_usage_end_year_offset { get; set; }

    // week 6
    public bool week6_enabled { get; set; }
    public decimal week6_hours_per_month { get; set; }
    public int week6_earning_start_month { get; set; }
    public int week6_earning_end_month { get; set; }
    public int week6_usage_start_month { get; set; }
    public int week6_usage_start_year_offset { get; set; }
    public int week6_usage_end_month { get; set; }
    public int week6_usage_end_year_offset { get; set; }

    // main holiday and notice
    public int main_holiday_length_days { get; set; }
    public int main_holiday_start_month { get; set; }
    public int main_holiday_end_month { get; set; }
    public int main_holiday_notice_months { get; set; }
    public int other_holiday_notice_months { get; set; }

    // standard (full time) working week, same format as an employee's schedule
    public ScheduleDTO standard_week { get; set; }

    // transfer
    public bool transfer_allowed { get; set; }
    public int transfer_max_days { get; set; }
    public int transfer_weeks1to5_deadline_month { get; set; }
    public int transfer_weeks1to5_deadline_day { get; set; }
    public int transfer_week6_deadline_month { get; set; }
    public int transfer_week6_deadline_day { get; set; }

    // holiday debt
    public int max_holiday_debt_days { get; set; }
    public int non_negative_balance_month { get; set; }
    public int non_negative_balance_day { get; set; }

    public RuleSetDTO()
    {
    }

    // checks the values themselves (ranges, consistency). the checks that need the db
    // (date already used, months already accrued) are in RulesetService.
    // returns null if the rule set is valid, otherwise the error message
    public string? validate()
    {
        if (effective_from.Day != 1)
        {
            return "effective_from must be the 1st of a month";
        }

        string? error =
            check_month("weeks1to5_earning_start_month", weeks1to5_earning_start_month)
            ?? check_month("weeks1to5_earning_end_month", weeks1to5_earning_end_month)
            ?? check_month("weeks1to5_usage_start_month", weeks1to5_usage_start_month)
            ?? check_month("weeks1to5_usage_end_month", weeks1to5_usage_end_month)
            ?? check_month("week6_earning_start_month", week6_earning_start_month)
            ?? check_month("week6_earning_end_month", week6_earning_end_month)
            ?? check_month("week6_usage_start_month", week6_usage_start_month)
            ?? check_month("week6_usage_end_month", week6_usage_end_month)
            ?? check_month("main_holiday_start_month", main_holiday_start_month)
            ?? check_month("main_holiday_end_month", main_holiday_end_month)
            ?? check_day_of_month("transfer_weeks1to5_deadline", transfer_weeks1to5_deadline_month, transfer_weeks1to5_deadline_day)
            ?? check_day_of_month("transfer_week6_deadline", transfer_week6_deadline_month, transfer_week6_deadline_day)
            ?? check_day_of_month("non_negative_balance", non_negative_balance_month, non_negative_balance_day)
            ?? check_earning_period("weeks 1-5", weeks1to5_earning_start_month, weeks1to5_earning_end_month)
            ?? check_earning_period("week 6", week6_earning_start_month, week6_earning_end_month)
            ?? check_usage_period("weeks 1-5", weeks1to5_usage_start_month, weeks1to5_usage_start_year_offset,
                weeks1to5_usage_end_month, weeks1to5_usage_end_year_offset)
            ?? check_usage_period("week 6", week6_usage_start_month, week6_usage_start_year_offset,
                week6_usage_end_month, week6_usage_end_year_offset);
        if (error != null)
        {
            return error;
        }

        if (weeks1to5_month_rate <= 0)
        {
            return "weeks1to5_month_rate must be greater than 0";
        }
        if (week6_hours_per_month < 0)
        {
            return "week6_hours_per_month can not be negative";
        }
        if (main_holiday_length_days <= 0)
        {
            return "main_holiday_length_days must be greater than 0";
        }
        if (main_holiday_end_month < main_holiday_start_month)
        {
            return "main holiday window: the end month must not be before the start month";
        }
        if (main_holiday_notice_months < 0 || other_holiday_notice_months < 0)
        {
            return "notice months can not be negative";
        }
        if (transfer_max_days < 0)
        {
            return "transfer_max_days can not be negative";
        }
        if (max_holiday_debt_days < 0)
        {
            return "max_holiday_debt_days can not be negative";
        }

        if (standard_week == null)
        {
            return "standard_week is required";
        }
        string? week_error = standard_week.validate();
        if (week_error != null)
        {
            return "standard_week: " + week_error;
        }

        return null;
    }

    private static string? check_month(string name, int month)
    {
        return month is < 1 or > 12 ? name + " must be between 1 and 12" : null;
    }

    private static string? check_day_of_month(string name, int month, int day)
    {
        string? month_error = check_month(name + "_month", month);
        if (month_error != null)
        {
            return month_error;
        }
        // a leap year is used, so 29 February is allowed
        int max_day = DateTime.DaysInMonth(2000, month);
        return day < 1 || day > max_day ? $"{name}_day must be between 1 and {max_day}" : null;
    }

    // an earning period is always one year: it ends in the month before the start month (Sep -> Aug, Jan -> Dec)
    private static string? check_earning_period(string name, int start_month, int end_month)
    {
        int expected_end = start_month == 1 ? 12 : start_month - 1;
        return end_month != expected_end
            ? $"{name}: the earning period must be one year, an earning period starting in month {start_month} ends in month {expected_end}"
            : null;
    }

    // year offsets are relative to the year the earning period starts in, the usage period can not end before it starts
    private static string? check_usage_period(string name, int start_month, int start_offset, int end_month, int end_offset)
    {
        if (start_offset < 0 || end_offset < 0)
        {
            return $"{name}: usage year offsets can not be negative";
        }
        int start = start_offset * 12 + start_month;
        int end = end_offset * 12 + end_month;
        return end < start ? $"{name}: the usage period ends before it starts" : null;
    }

    // the same shape is returned by get_parameters, so the admin form can be filled with it and sent back
    public static RuleSetDTO from_rule_set(RuleSet rs)
    {
        return new RuleSetDTO
        {
            effective_from = rs.effective_from,

            weeks1to5_month_rate = rs.weeks1to5_month_rate,
            weeks1to5_earning_start_month = rs.weeks1to5_earning_start_month,
            weeks1to5_earning_end_month = rs.weeks1to5_earning_end_month,
            weeks1to5_usage_start_month = rs.weeks1to5_usage_start_month,
            weeks1to5_usage_start_year_offset = rs.weeks1to5_usage_start_year_offset,
            weeks1to5_usage_end_month = rs.weeks1to5_usage_end_month,
            weeks1to5_usage_end_year_offset = rs.weeks1to5_usage_end_year_offset,

            week6_enabled = rs.week6_enabled,
            week6_hours_per_month = rs.week6_hours_per_month,
            week6_earning_start_month = rs.week6_earning_start_month,
            week6_earning_end_month = rs.week6_earning_end_month,
            week6_usage_start_month = rs.week6_usage_start_month,
            week6_usage_start_year_offset = rs.week6_usage_start_year_offset,
            week6_usage_end_month = rs.week6_usage_end_month,
            week6_usage_end_year_offset = rs.week6_usage_end_year_offset,

            main_holiday_length_days = rs.main_holiday_length_days,
            main_holiday_start_month = rs.main_holiday_start_month,
            main_holiday_end_month = rs.main_holiday_end_month,
            main_holiday_notice_months = rs.main_holiday_notice_months,
            other_holiday_notice_months = rs.other_holiday_notice_months,

            standard_week = new ScheduleDTO
            {
                monday_start = rs.monday_start, monday_end = rs.monday_end,
                tuesday_start = rs.tuesday_start, tuesday_end = rs.tuesday_end,
                wednesday_start = rs.wednesday_start, wednesday_end = rs.wednesday_end,
                thursday_start = rs.thursday_start, thursday_end = rs.thursday_end,
                friday_start = rs.friday_start, friday_end = rs.friday_end
            },

            transfer_allowed = rs.transfer_allowed,
            transfer_max_days = rs.transfer_max_days,
            transfer_weeks1to5_deadline_month = rs.transfer_weeks1to5_deadline_month,
            transfer_weeks1to5_deadline_day = rs.transfer_weeks1to5_deadline_day,
            transfer_week6_deadline_month = rs.transfer_week6_deadline_month,
            transfer_week6_deadline_day = rs.transfer_week6_deadline_day,

            max_holiday_debt_days = rs.max_holiday_debt_days,
            non_negative_balance_month = rs.non_negative_balance_month,
            non_negative_balance_day = rs.non_negative_balance_day
        };
    }

    public RuleSet to_rule_set()
    {
        return new RuleSet
        {
            effective_from = effective_from,

            weeks1to5_month_rate = weeks1to5_month_rate,
            weeks1to5_earning_start_month = weeks1to5_earning_start_month,
            weeks1to5_earning_end_month = weeks1to5_earning_end_month,
            weeks1to5_usage_start_month = weeks1to5_usage_start_month,
            weeks1to5_usage_start_year_offset = weeks1to5_usage_start_year_offset,
            weeks1to5_usage_end_month = weeks1to5_usage_end_month,
            weeks1to5_usage_end_year_offset = weeks1to5_usage_end_year_offset,

            week6_enabled = week6_enabled,
            week6_hours_per_month = week6_hours_per_month,
            week6_earning_start_month = week6_earning_start_month,
            week6_earning_end_month = week6_earning_end_month,
            week6_usage_start_month = week6_usage_start_month,
            week6_usage_start_year_offset = week6_usage_start_year_offset,
            week6_usage_end_month = week6_usage_end_month,
            week6_usage_end_year_offset = week6_usage_end_year_offset,

            main_holiday_length_days = main_holiday_length_days,
            main_holiday_start_month = main_holiday_start_month,
            main_holiday_end_month = main_holiday_end_month,
            main_holiday_notice_months = main_holiday_notice_months,
            other_holiday_notice_months = other_holiday_notice_months,

            monday_start = standard_week.monday_start, monday_end = standard_week.monday_end,
            tuesday_start = standard_week.tuesday_start, tuesday_end = standard_week.tuesday_end,
            wednesday_start = standard_week.wednesday_start, wednesday_end = standard_week.wednesday_end,
            thursday_start = standard_week.thursday_start, thursday_end = standard_week.thursday_end,
            friday_start = standard_week.friday_start, friday_end = standard_week.friday_end,

            transfer_allowed = transfer_allowed,
            transfer_max_days = transfer_max_days,
            transfer_weeks1to5_deadline_month = transfer_weeks1to5_deadline_month,
            transfer_weeks1to5_deadline_day = transfer_weeks1to5_deadline_day,
            transfer_week6_deadline_month = transfer_week6_deadline_month,
            transfer_week6_deadline_day = transfer_week6_deadline_day,

            max_holiday_debt_days = max_holiday_debt_days,
            non_negative_balance_month = non_negative_balance_month,
            non_negative_balance_day = non_negative_balance_day
        };
    }
}
